namespace LSE.AutoCADElectrical.CatalogTools;
public static class CatalogTransactionService{
 public static string Execute(AppSettings s,CatalogAddRequest q){string backupRoot=Path.Combine(Path.GetDirectoryName(s.CatalogPath)??Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"LSE_Catalog_Backups");string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");string backup=Path.Combine(backupRoot,stamp);Directory.CreateDirectory(backup);string backupFile=Path.Combine(backup,Path.GetFileName(s.CatalogPath));File.Copy(s.CatalogPath,backupFile,true);var log=new List<string>{$"Started: {DateTime.Now:s}",$"Catalog: {s.CatalogPath}",$"Backup: {backupFile}",$"Record: {q.TableName} | {q.Manufacturer} | {q.Catalog} | USER1={q.User1}"};bool vault=false;
  try{var svc=new AccessCatalogService(s.CatalogPath);if(svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("That manufacturer/catalog number already exists in the selected family.");if(VaultCatalogService.Enabled(s)){VaultCatalogService.Checkout(s,log);vault=true;log.Add("Vault checkout: PASS");}else VaultProbe.RequireWritable(new[]{s.CatalogPath});svc.AddRecord(q);if(!svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("Read-back verification failed after insert.");log.Add("Database insert/read-back: PASS");if(vault){VaultCatalogService.Checkin(s,"Add electrical catalog component "+q.Manufacturer+" "+q.Catalog,log);log.Add("Vault checkin: PASS");}else log.AddRange(VaultProbe.CheckinReminder(new[]{s.CatalogPath}));log.Add("Status: SUCCESS");File.WriteAllLines(Path.Combine(backup,"TransactionReport.txt"),log);return string.Join(Environment.NewLine,log);}
  catch(Exception ex){log.Add("ERROR: "+ex);try{File.Copy(backupFile,s.CatalogPath,true);log.Add("Local rollback: PASS");}catch(Exception rx){log.Add("Local rollback: FAILED "+rx.Message);}if(vault)try{VaultCatalogService.UndoCheckout(s,log);log.Add("Vault undo checkout: PASS");}catch(Exception vx){log.Add("Vault undo checkout: FAILED "+vx.Message);}File.WriteAllLines(Path.Combine(backup,"TransactionReport.txt"),log);throw new InvalidOperationException(string.Join(Environment.NewLine,log),ex);}
  finally{VaultCatalogService.EndSession();}
 }
}
